"""Independent Auto Stream control screen; shared shell injected by Scene gateway."""
from fastapi import APIRouter
from fastapi.responses import HTMLResponse

router = APIRouter(prefix="/engine", tags=["Auto Stream Studio"])

PAGE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Auto Stream</title>
<style>
:root{font-family:Inter,system-ui,-apple-system,Segoe UI,Arial,sans-serif;color:#172136;background:#f5f7fb;--line:#e2e7f0;--muted:#64748b;--accent:#4f46e5;--good:#15803d;--warn:#a16207}
*{box-sizing:border-box}body{margin:0;background:#f5f7fb}main{max-width:1320px;margin:0 auto;padding:24px 20px 40px}h1,h2,h3{margin:0 0 10px}h1{font-size:25px}h2{font-size:18px}h3{font-size:14px}.lede{color:var(--muted);font-size:13px;margin:0 0 18px}.rail{display:flex;gap:6px;overflow-x:auto;border-bottom:1px solid #cfd7e5;margin-bottom:18px}.rail button{border:1px solid #cfd7e5;border-bottom:0;background:#eef1f6;color:#35445f;padding:11px 16px;border-radius:8px 8px 0 0;cursor:pointer;font-weight:750;white-space:nowrap}.rail button[aria-selected=true]{background:#fff;color:var(--accent);border-top:3px solid var(--accent);padding-top:9px}.panel{background:#fff;border:1px solid var(--line);border-radius:14px;padding:18px;box-shadow:0 4px 18px #1f2a440b;margin-bottom:14px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.stat{border:1px solid var(--line);border-radius:12px;padding:14px}.stat b{display:block;font-size:24px}.stat span,.muted{color:var(--muted);font-size:12px}.row{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.item{border:1px solid var(--line);border-radius:10px;padding:12px;margin:9px 0}.item strong{display:block}.btn,button{border:1px solid #cbd5e1;background:#fff;color:#172136;padding:9px 12px;border-radius:8px;cursor:pointer;font-weight:700}.btn.primary,button.primary{background:var(--accent);color:#fff;border-color:var(--accent)}.btn.good{background:var(--good);color:#fff;border-color:var(--good)}.btn.warn{background:#fef3c7;color:#854d0e;border-color:#fcd34d}.btn:disabled,button:disabled{opacity:.5;cursor:not-allowed}input,select,textarea{width:100%;border:1px solid #cbd5e1;border-radius:8px;padding:10px;font:inherit;background:#fff}label{font-size:12px;font-weight:750;display:block;margin:9px 0 5px}.message{white-space:pre-wrap;background:#eef2ff;border-radius:9px;padding:11px;color:#334155;font-size:13px}.danger{color:#b91c1c}.mono{font:12px ui-monospace,SFMono-Regular,Consolas,monospace;overflow-wrap:anywhere}.queue-state{font-size:11px;border-radius:999px;padding:5px 8px;background:#eef2f7;color:#475569}.queue-state.live{background:#dcfce7;color:#166534}.queue-state.failed{background:#fee2e2;color:#991b1b}.drawer{border-top:1px solid var(--line);margin-top:14px;padding-top:12px}.hide{display:none!important}@media(max-width:700px){main{padding:16px 12px}.rail button{padding:10px 12px;font-size:12px}.panel{padding:14px}.row .grow{flex:1 1 100%}}
.studio-workspace{display:grid;grid-template-columns:200px minmax(0,1fr) 220px;gap:12px;margin-bottom:16px}.studio-monitor{aspect-ratio:16/9;background:#111827;border-radius:10px;display:grid;place-items:center;overflow:hidden}.studio-monitor video{width:100%;height:100%;object-fit:contain}.studio-dock{border:1px solid var(--line);border-radius:10px;padding:12px;min-width:0}.studio-dock button{margin:3px}.studio-status{padding:10px;background:#eef2ff;border-radius:8px}.studio-workspace input[type=range]{padding:0}input[type=checkbox]{width:auto}main{min-width:0}.panel,.grid>*{min-width:0}@media(max-width:900px){.studio-workspace{grid-template-columns:1fr 1fr}.studio-monitor-wrap{grid-column:1/-1;grid-row:1}}@media(max-width:500px){.studio-workspace{grid-template-columns:1fr}.studio-monitor-wrap{grid-column:auto}.grid{grid-template-columns:1fr}button,input,select{min-height:42px}}</style></head><body><main>
<h1>Auto Stream</h1><p class="lede">Independent prerecorded YouTube Live studio · one stream supervisor · Auto Uploader data remains isolated.</p>
<nav class="rail" aria-label="Auto Stream primary tabs">
<button data-tab="dashboard" aria-selected="true">Dashboard</button>
<button data-tab="channels" aria-selected="false">Channels</button>
<button data-tab="sheets-sync" aria-selected="false">Sheets Sync</button>
<button data-tab="live-studio" aria-selected="false">Live Studio</button>
<button data-tab="live-queue" aria-selected="false">Live Queue</button>
</nav>
<section id="dashboard" role="tabpanel" class="panel">
<h2>Dashboard</h2><div class="grid"><div class="stat"><b id="channel-count">0</b><span>Authorized channels</span></div><div class="stat"><b id="job-count">0</b><span>Queued streaming jobs</span></div><div class="stat"><b id="active-count">0</b><span>Encoder sessions</span></div><div class="stat"><b id="health-state">—</b><span>Engine health</span></div></div>
<div class="grid" id="stream-metrics"></div><div class="grid"><section class="item"><h3>Active Live Sessions</h3><div id="active-sessions"></div></section><section class="item"><h3>Upcoming Streams</h3><div id="upcoming-streams"></div></section><section class="item"><h3>Recent Activity</h3><div id="recent-streams"></div></section></div><p id="health" class="message">Loading status…</p>

</section>
<section id="channels" role="tabpanel" class="panel hide"><div class="row"><div class="grow"><h2>YouTube Channels</h2><p class="muted">Inventory and authorization are separate. Metadata import never grants Live access.</p></div><button class="primary" id="connect-youtube">Connect YouTube channel</button><button id="refresh-channels">Refresh</button></div><nav class="row" aria-label="Channel sections"><button id="show-manager">Channel Manager</button><button id="show-accounts">Accounts &amp; Tokens</button></nav><div id="manager-panel"><label>Search channels</label><input id="channel-search" type="search"><div id="channel-list"></div></div><div id="accounts-panel" class="hide"><div class="drawer"><details><summary>1. Shared OAuth Client</summary><label>Google Cloud OAuth Web client JSON</label><input id="oauth-json" type="file" accept=".json,application/json"><button id="upload-oauth-json">Validate &amp; Save JSON</button><p class="muted">Stored encrypted on VPS; this panel never exposes the secret and is not a primary tab.</p><div class="grid"><div><label>Client ID</label><input id="oauth-client-id" autocomplete="off"></div><div><label>Client Secret</label><input id="oauth-client-secret" type="password" autocomplete="new-password"></div></div><div class="row"><button class="primary" id="save-oauth">Save OAuth Client</button><button id="remove-oauth">Remove Saved Client</button></div><p id="oauth-state" class="muted"></p></details></div><h3>2. Verify &amp; Save Channel Token</h3><p class="muted">Connect a selected UC Channel ID. Google authorization must match that exact channel, including Brand Accounts.</p><label>Expected channel</label><select id="expected-channel"></select><button id="connect-selected">Connect / Reconnect selected channel</button><h3>3. Channels Requiring Authorization</h3><div id="needs-auth"></div><h3>4. Connected Channels</h3><div id="connected-channels"></div><h3>5. OAuth &amp; Token Vault</h3><p id="vault-state" class="message">Loading vault status…</p></div><div class="drawer"><h3>Import inventory metadata</h3><div class="grid"><div><label>Channel ID</label><input id="import-channel-id" placeholder="UC…"></div><div><label>Channel name</label><input id="import-channel-title"></div></div><button id="import-channel">Import metadata only</button></div></section>
<section id="sheets-sync" role="tabpanel" class="panel hide"><h2>Sheets Sync</h2><p class="muted">Separate read-only channel inventory/schedule source. Preview and Sync create DRAFT records only; they never start a stream.</p><div class="grid"><div><label>Authorized channel</label><select id="sheet-channel"></select></div><div><label for="sheet-name">Sheet Name</label><input id="sheet-name" maxlength="150"><label for="sheet-id">Google Sheet Link</label><input id="sheet-id" type="url" placeholder="https://docs.google.com/spreadsheets/d/…/edit"></div><div><label for="sheet-worksheet">Worksheet (discovered from link)</label><select id="sheet-worksheet"><option value="">Auto detect</option></select></div></div><button class="primary" id="add-sheet">Add Sheet Source</button><div id="sheet-list"></div></section>
<section id="live-studio" role="tabpanel" class="panel hide"><h2>Live Studio</h2><div class="row"><button id="save-studio" class="primary">Save configuration</button><span id="studio-save-state" class="muted">Server-persisted scenes · prerecorded video source</span></div><div class="studio-workspace"><aside class="studio-dock"><h3>Scenes</h3><div id="scene-list"></div><button id="add-scene">Create</button><button id="rename-scene">Rename</button><button id="duplicate-scene">Duplicate</button><button id="delete-scene">Delete</button><button id="move-scene">Move up</button><h3>Sources</h3><div id="source-list"></div><label>Existing video</label><select id="existing-media"></select><button id="add-source">Add video source</button></aside><div class="studio-monitor-wrap"><div class="studio-monitor"><video id="composition-preview" controls playsinline preload="metadata"></video></div><p id="composition-state" class="studio-status">Choose a scene and add a video source.</p></div><aside class="studio-dock"><h3>Audio Mixer</h3><label>Selected source volume</label><input id="source-volume" type="range" min="0" max="2" step="0.05" value="1"><button id="source-mute">Mute / Unmute</button><p class="muted">Preview monitoring. Encoder mix support remains pending; no fabricated meters.</p><h3>Stream Controls</h3><p class="muted">Prepare and operate an explicitly selected queue job below. Saving a scene never starts broadcasting.</p><label>Queue job</label><select id="selected-job"></select><button id="studio-prepare">Prepare</button><button id="studio-stop">Stop encoder</button><div id="encoder-status" class="studio-status">Loading encoder health…</div></aside></div><p class="muted">Prepare media before streaming. OAuth mode controls YouTube resources; manual-key mode controls encoder delivery only.</p><div class="grid"><div><label>Authorized channel</label><select id="job-channel"></select></div><div><label>Media path</label><input id="job-media" placeholder="uploads/video.mp4"></div><div><label>Title</label><input id="job-title" maxlength="100"></div><div><label>Loop count</label><input id="job-loops" type="number" min="1" value="1"></div></div><label>Description</label><textarea id="job-description" rows="3"></textarea><div class="row"><label><input id="job-unlimited" type="checkbox"> Unlimited loop</label><label>Privacy <select id="job-privacy"><option>private</option><option>unlisted</option><option>public</option></select></label><label class="grow">PC video <input id="media-file" type="file" accept="video/*"></label><button id="upload-media">Upload and checksum</button></div><p id="studio-note" class="message">Publishing and Go Live are OFF by default.</p><button class="primary" id="create-job">Create DRAFT / queue</button><div class="drawer"><h3>Manual RTMPS control</h3><p class="muted">The stream key is sent only over the authenticated HTTPS request and is never saved in the job database or browser storage.</p><div class="grid"><div><label>RTMPS ingest URL</label><input id="manual-url" value="rtmps://a.rtmps.youtube.com/live2"></div><div><label>Stream key</label><input id="manual-key" type="password" autocomplete="off"></div></div><button class="btn warn" id="manual-start">Start manual RTMPS for selected queue item</button></div></section>
<section id="live-queue" role="tabpanel" class="panel hide"><div class="row"><div class="grow"><h2>Live Queue</h2><p class="muted">Durable states are local truth; YouTube LIVE is shown only after remote verification.</p></div><button id="refresh-jobs">Refresh</button></div><div id="job-list"></div></section>
<div id="msg" class="message hide" role="status" aria-live="polite"></div>
</main>
<script>
"use strict";
const root="/short-stream/engine";
const qs=id=>document.getElementById(id), msg=qs("msg");
let channels=[],jobs=[],flags={};let studioConfig={name:"Live Studio",active_scene:0,scenes:[{name:"Scene 1",sources:[]}]},sourceIndex=0;
function note(s){msg.textContent=s;msg.classList.remove("hide")}
async function api(path,method="GET",body=null,form=false){const r=await fetch(root+path,{method,credentials:"same-origin",headers:form?{}:{"X-Auto-Stream-Config-Action":"1",...(body?{"Content-Type":"application/json"}:{})},body:form?body:(body?JSON.stringify(body):undefined)});let p={};try{p=await r.json()}catch(_){ }if(!r.ok)throw Error(typeof p.detail==="string"?p.detail:"Request failed");return p}
function render(id,items,fn){const el=qs(id);el.replaceChildren();if(!items.length){el.innerHTML='<p class="muted">None yet.</p>';return}items.forEach(x=>{const d=document.createElement("div");d.className="item";fn(d,x);el.appendChild(d)})}
function addText(el,text,cls=""){const p=document.createElement("p");p.textContent=text;if(cls)p.className=cls;el.appendChild(p)}
function fillChannels(){for(const id of ["sheet-channel","job-channel","expected-channel"]){const s=qs(id);s.replaceChildren();channels.filter(c=>id==="expected-channel"||c.authorized).forEach(c=>{const o=document.createElement("option");o.value=c.id;o.textContent=c.title+" ("+c.id+")";s.appendChild(o)})}}
async function loadChannels(){channels=(await api("/channels")).channels||[];render("channel-list",channels.filter(c=>(c.title+" "+c.id).toLowerCase().includes(qs("channel-search").value.toLowerCase())),(el,c)=>{addText(el,c.title+" — "+c.id);addText(el,c.authorized?"OAuth Live authorization verified":"Inventory-only; connect OAuth for Live control","muted");if(c.authorized){const b=document.createElement("button");b.textContent="Disconnect";b.onclick=async()=>{try{await api("/channels/"+encodeURIComponent(c.id)+"/disconnect","POST");loadChannels()}catch(e){note(e.message)}};el.appendChild(b)}});fillChannels();render("needs-auth",channels.filter(c=>!c.authorized),(el,c)=>addText(el,c.title+" · "+c.id));render("connected-channels",channels.filter(c=>c.authorized),(el,c)=>addText(el,c.title+" · "+c.id+" · Authorized"))}
async function loadSheets(){const data=await api("/sheets");render("sheet-list",data.sources||[],(el,s)=>{addText(el,(s.name||s.spreadsheet_id)+" — "+s.channel_id,"mono");const row=document.createElement("div");row.className="row";for(const [label,dry] of [["Preview",true],["Sync DRAFTs",false]]){const b=document.createElement("button");b.textContent=label;b.onclick=async()=>{try{const r=await api("/sheets/"+encodeURIComponent(s.id)+"/sync?dry_run="+dry,"POST");note("Rows: "+r.total+" · Drafts: "+r.created+" · Errors: "+r.errors.length)}catch(e){note(e.message)}};row.appendChild(b)}el.appendChild(row)})}
function jobText(j){return j.title+" · "+j.id+" · "+j.status}
async function loadJobs(){jobs=(await api("/jobs")).jobs||[];const selected=qs("selected-job"),previous=selected.value;selected.replaceChildren();jobs.forEach(j=>{const o=document.createElement("option");o.value=j.id;o.textContent=j.title+" · "+j.status;selected.appendChild(o)});if(jobs.some(j=>j.id===previous))selected.value=previous;render("job-list",jobs,(el,j)=>{addText(el,jobText(j));addText(el,"Channel: "+j.channel_id+" · mode: "+(j.mode||"OAuth/manual") ,"muted");const row=document.createElement("div");row.className="row";const prep=document.createElement("button");prep.textContent="Prepare";prep.disabled=!["DRAFT","READY","SCHEDULED"].includes(j.status);prep.onclick=async()=>{try{await api("/jobs/"+j.id+"/prepare","POST");loadJobs()}catch(e){note(e.message)}};row.appendChild(prep);const oauth=document.createElement("button");oauth.textContent="Create private OAuth broadcast";oauth.disabled=!flags.youtube_mutations_enabled||!["READY","SCHEDULED"].includes(j.status);oauth.onclick=async()=>{try{await api("/jobs/"+j.id+"/broadcast/provision","POST");loadJobs();note("Private YouTube broadcast created; not Live.")}catch(e){note(e.message)}};row.appendChild(oauth);const verify=document.createElement("button");verify.textContent="Verify remote";verify.onclick=async()=>{try{const r=await api("/jobs/"+j.id+"/broadcast/verify");note("YouTube="+r.youtube_broadcast_status+" · ingest="+r.youtube_ingest_status+" · verifiedLive="+r.youtube_verified_live)}catch(e){note(e.message)}};row.appendChild(verify);const stop=document.createElement("button");stop.textContent="Stop";stop.disabled=!["STARTING","INGESTING","STOPPING"].includes(j.status);stop.onclick=async()=>{try{await api("/jobs/"+j.id+"/stop","POST");loadJobs()}catch(e){note(e.message)}};row.appendChild(stop);for(const [label,action] of [["Duplicate","duplicate"],["Cancel","cancel"]]){const b=document.createElement("button");b.textContent=label;b.disabled=action==="cancel"&&!["DRAFT","READY","SCHEDULED","FAILED","INTERRUPTED"].includes(j.status);b.onclick=async()=>{try{await api("/jobs/"+j.id+"/"+action,"POST");await loadJobs()}catch(e){note(e.message)}};row.appendChild(b)}el.appendChild(row)})}
async function loadHealth(){const [h,i,y,d]=await Promise.all([api("/health"),api("/integrations/health"),api("/youtube/health"),api("/dashboard")]);flags={...y};qs("vault-state").textContent="Encryption vault: "+(i.vault_ready?"Ready":"Unavailable")+" · Authorized channels: "+i.channels_connected;qs("channel-count").textContent=d.authorized_channels;qs("job-count").textContent=d.queued;
render("stream-metrics",[["YouTube Live verified",d.live_verified===null?"Unverified":d.live_verified],["Scheduled streams",d.scheduled],["Completed streams",d.completed],["Failed streams",d.failed]],(el,x)=>{addText(el,String(x[1]));addText(el,x[0],"muted")});
render("active-sessions",jobs.filter(j=>["LIVE","INGESTING","STARTING"].includes(j.status)),(el,j)=>addText(el,jobText(j)));
render("upcoming-streams",d.upcoming,(el,j)=>addText(el,jobText(j)+" · "+j.scheduled_at));
render("recent-streams",d.recent,(el,j)=>addText(el,jobText(j)));qs("active-count").textContent=d.active_encoders;qs("encoder-status").textContent="Encoder sessions: "+h.encoder_sessions+" · "+(h.ok?"Healthy":"Degraded");qs("health-state").textContent=h.ok?"OK":"DEGRADED";qs("health").textContent="Engine="+(h.ok?"connected":"unavailable")+" · encoder="+h.encoder_sessions+" · publishing="+(h.publishing_enabled?"ON":"OFF")+" · YouTube LIVE is remote-only";qs("studio-note").textContent="OAuth mutations="+(y.youtube_mutations_enabled?"ON":"OFF")+" · FFmpeg publishing="+(y.publishing_enabled?"ON":"OFF")+" · Go Live="+(y.go_live_enabled?"ON":"OFF")}
async function saveOAuth(){try{await api("/oauth/client","POST",{client_id:qs("oauth-client-id").value.trim(),client_secret:qs("oauth-client-secret").value},{})}catch(e){note(e.message)}}
qs("connect-youtube").onclick=async()=>{try{const r=await api("/oauth/start?with_sheets=1");location.assign(r.authorization_url)}catch(e){note(e.message)}};
qs("upload-oauth-json").onclick=async()=>{try{const file=qs("oauth-json").files[0];if(!file)throw Error("Choose a Google OAuth Web client JSON file.");if(file.size>32768)throw Error("OAuth JSON must be smaller than 32 KB");let doc;try{doc=JSON.parse(await file.text())}catch(_){throw Error("Malformed JSON file")}const r=await api("/oauth/client/json","POST",doc);qs("oauth-json").value="";qs("oauth-state").textContent="Encrypted client saved: "+r.client_id}catch(e){note(e.message)}};
qs("show-manager").onclick=()=>{qs("manager-panel").classList.remove("hide");qs("accounts-panel").classList.add("hide")};
qs("show-accounts").onclick=()=>{qs("manager-panel").classList.add("hide");qs("accounts-panel").classList.remove("hide")};
qs("channel-search").oninput=()=>loadChannels().catch(e=>note(e.message));
qs("connect-selected").onclick=async()=>{try{const id=qs("expected-channel").value;if(!id)throw Error("Import or select a channel first");const r=await api("/oauth/start?with_sheets=1&expected_channel="+encodeURIComponent(id));location.assign(r.authorization_url)}catch(e){note(e.message)}};
qs("refresh-channels").onclick=()=>loadChannels().catch(e=>note(e.message));
qs("import-channel").onclick=async()=>{try{await api("/channels/import","POST",{channel_id:qs("import-channel-id").value,title:qs("import-channel-title").value});loadChannels();note("Inventory metadata imported; authorization still required.")}catch(e){note(e.message)}};
qs("add-sheet").onclick=async()=>{try{const linked=await api("/sheets","POST",{channel_id:qs("sheet-channel").value,name:qs("sheet-name").value,sheet_url:qs("sheet-id").value,worksheet_id:qs("sheet-worksheet").value||undefined});if(linked.requires_worksheet){const select=qs("sheet-worksheet");select.replaceChildren();linked.worksheets.forEach(t=>{const o=document.createElement("option");o.value=t.sheetId;o.textContent=t.title;select.appendChild(o)});note("Select the worksheet and add the source again.");return}loadSheets();note("Sheet source linked; no stream started.")}catch(e){note(e.message)}};
qs("upload-media").onclick=async()=>{const f=qs("media-file").files[0];if(!f){note("Choose a video first.");return}const form=new FormData();form.append("file",f);try{const r=await api("/media/upload","POST",form,true);qs("job-media").value=r.media_path;note("Uploaded "+r.bytes+" bytes; SHA-256 "+r.sha256)}catch(e){note(e.message)}};
qs("create-job").onclick=async()=>{try{const c=qs("job-channel").value;if(!c)throw Error("Select an authorized channel.");const j=await api("/jobs","POST",{channel_id:c,media_path:qs("job-media").value.trim(),title:qs("job-title").value.trim(),description:qs("job-description").value,privacy:qs("job-privacy").value,loop_count:+qs("job-loops").value,unlimited:qs("job-unlimited").checked,idempotency_key:"studio-"+(crypto.randomUUID?crypto.randomUUID():String(Date.now()))});note("DRAFT created "+j.id+"; prepare it before any external action.");loadJobs()}catch(e){note(e.message)}};
qs("manual-start").onclick=async()=>{const j=jobs.find(x=>x.id===qs("selected-job").value&&["READY","SCHEDULED"].includes(x.status));if(!j){note("Prepare a READY job first.");return}try{const r=await api("/jobs/"+j.id+"/broadcast/manual-ingest","POST",{ingest_url:qs("manual-url").value,stream_key:qs("manual-key").value});qs("manual-key").value="";note("Manual encoder started. YouTube LIVE must be verified in YouTube Studio.");loadJobs()}catch(e){note(e.message)}};
qs("save-oauth").onclick=async()=>{try{const r=await api("/oauth/client","POST",{client_id:qs("oauth-client-id").value.trim(),client_secret:qs("oauth-client-secret").value});qs("oauth-client-secret").value="";qs("oauth-state").textContent="Saved encrypted OAuth client: "+r.client_id}catch(e){note(e.message)}};
qs("remove-oauth").onclick=async()=>{try{await api("/oauth/client","DELETE");qs("oauth-state").textContent="Saved client removed."}catch(e){note(e.message)}};
qs("refresh-jobs").onclick=()=>loadJobs().catch(e=>note(e.message));
const tabs=[...document.querySelectorAll("[data-tab]")], identity=document.querySelector("meta[name=vps1-username]")?.content||"", stateKey=identity?"vps1.autostream.tab.v2:"+identity:"";
function openTab(id){if(!tabs.some(x=>x.dataset.tab===id))id="dashboard";tabs.forEach(x=>x.setAttribute("aria-selected",String(x.dataset.tab===id)));document.querySelectorAll("[role=tabpanel]").forEach(x=>x.classList.toggle("hide",x.id!==id));if(stateKey)try{sessionStorage.setItem(stateKey,id)}catch(_){}}
tabs.forEach(x=>x.onclick=()=>openTab(x.dataset.tab));let restore="dashboard";if(stateKey)try{restore=sessionStorage.getItem(stateKey)||"dashboard"}catch(_){}openTab(restore);
function activeScene(){return studioConfig.scenes[studioConfig.active_scene]}
function renderStudio(){render("scene-list",studioConfig.scenes,(el,scene)=>{const i=studioConfig.scenes.indexOf(scene),b=document.createElement("button");b.textContent=(i===studioConfig.active_scene?"● ":"")+scene.name;b.onclick=()=>{studioConfig.active_scene=i;sourceIndex=0;renderStudio()};el.appendChild(b)});render("source-list",activeScene().sources,(el,src)=>{const i=activeScene().sources.indexOf(src);addText(el,src.media_path);for(const [label,action] of [["Select",()=>{sourceIndex=i;renderStudio()}],[src.visible?"Hide":"Show",()=>{src.visible=!src.visible;renderStudio()}],["Up",()=>{if(i>0){[activeScene().sources[i-1],activeScene().sources[i]]=[src,activeScene().sources[i-1]];sourceIndex=i-1;renderStudio()}}],["Remove",()=>{activeScene().sources.splice(i,1);sourceIndex=0;renderStudio()}]]){const b=document.createElement("button");b.textContent=label;b.onclick=action;el.appendChild(b)}});const src=activeScene().sources[sourceIndex],video=qs("composition-preview");if(src&&src.visible){const url=root+"/media/preview?media_path="+encodeURIComponent(src.media_path);if(video.getAttribute("src")!==url)video.src=url;video.muted=src.muted;video.volume=Math.min(1,src.volume);qs("source-volume").value=src.volume;qs("job-media").value=src.media_path;qs("composition-state").textContent=activeScene().name+" · "+src.media_path+" · Video preview"}else{video.removeAttribute("src");video.load();qs("composition-state").textContent=activeScene().name+" · No visible selected video"}}
qs("add-scene").onclick=()=>{studioConfig.scenes.push({name:"Scene "+(studioConfig.scenes.length+1),sources:[]});studioConfig.active_scene=studioConfig.scenes.length-1;renderStudio()};
qs("rename-scene").onclick=()=>{const name=prompt("Scene name",activeScene().name);if(name&&name.trim()){activeScene().name=name.trim().slice(0,100);renderStudio()}};
qs("duplicate-scene").onclick=()=>{studioConfig.scenes.push(JSON.parse(JSON.stringify(activeScene())));studioConfig.active_scene=studioConfig.scenes.length-1;activeScene().name+=" copy";renderStudio()};
qs("delete-scene").onclick=()=>{if(studioConfig.scenes.length===1){note("Keep at least one scene");return}studioConfig.scenes.splice(studioConfig.active_scene,1);studioConfig.active_scene=0;renderStudio()};
qs("move-scene").onclick=()=>{const i=studioConfig.active_scene;if(i>0){[studioConfig.scenes[i-1],studioConfig.scenes[i]]=[studioConfig.scenes[i],studioConfig.scenes[i-1]];studioConfig.active_scene--;renderStudio()}};
qs("add-source").onclick=()=>{const media=qs("existing-media").value||qs("job-media").value;if(!media){note("Upload or select a video first");return}activeScene().sources.push({type:"video",media_path:media,visible:true,muted:false,volume:1});sourceIndex=activeScene().sources.length-1;renderStudio()};
qs("source-volume").oninput=()=>{const src=activeScene().sources[sourceIndex];if(src){src.volume=+qs("source-volume").value;renderStudio()}};
qs("source-mute").onclick=()=>{const src=activeScene().sources[sourceIndex];if(src){src.muted=!src.muted;renderStudio()}};
qs("save-studio").onclick=async()=>{try{studioConfig=await api("/studio/config","PUT",studioConfig);qs("studio-save-state").textContent="Saved on server"}catch(e){note(e.message)}};
for(const [id,action] of [["studio-prepare","prepare"],["studio-stop","stop"]])qs(id).onclick=async()=>{try{const jid=qs("selected-job").value;if(!jid)throw Error("Select a queue job first");await api("/jobs/"+encodeURIComponent(jid)+"/"+action,"POST");await loadJobs()}catch(e){note(e.message)}};
async function initStudio(){try{studioConfig=await api("/studio/config");renderStudio();const media=(await api("/media")).media||[];media.forEach(m=>{const o=document.createElement("option");o.value=m.media_path;o.textContent=m.name;qs("existing-media").appendChild(o)})}catch(e){note(e.message)}}initStudio();
async function refreshAll(){try{await loadChannels();await loadSheets();await loadJobs();await loadHealth()}catch(e){note(e.message)}}refreshAll();setInterval(refreshAll,8000);
</script></body></html>'''

